add_action( 'admin_menu', 'perfectpixel_bulk_coupons_menu', 60 );

function perfectpixel_bulk_coupons_menu() {
	add_submenu_page( 'woocommerce', 'Μαζικά κουπόνια', 'Μαζικά κουπόνια', 'manage_woocommerce', 'perfectpixel-bulk-coupons', 'perfectpixel_bulk_coupons_page' );
}

function perfectpixel_bulk_coupons_page() {
	if ( ! current_user_can( 'manage_woocommerce' ) ) {
		return;
	}
	$created = array();
	if ( isset( $_POST['perfectpixel_bulk_coupons'] ) && check_admin_referer( 'perfectpixel_bulk_coupons' ) ) {
		$count  = min( 500, max( 1, absint( $_POST['count'] ?? 0 ) ) );
		$prefix = strtoupper( preg_replace( '/[^A-Za-z0-9_-]/', '', wp_unslash( $_POST['prefix'] ?? '' ) ) );
		$type   = in_array( $_POST['discount_type'] ?? '', array( 'percent', 'fixed_cart', 'fixed_product' ), true ) ? $_POST['discount_type'] : 'percent';
		$amount = wc_format_decimal( wp_unslash( $_POST['amount'] ?? 0 ) );
		$limit  = absint( $_POST['usage_limit'] ?? 1 );
		$expiry = sanitize_text_field( wp_unslash( $_POST['expiry'] ?? '' ) );
		for ( $i = 0; $i < $count; $i++ ) {
			do {
				$code = $prefix . strtoupper( wp_generate_password( 8, false ) );
			} while ( wc_get_coupon_id_by_code( $code ) );
			$coupon = new WC_Coupon();
			$coupon->set_code( $code );
			$coupon->set_discount_type( $type );
			$coupon->set_amount( $amount );
			$coupon->set_usage_limit( $limit );
			if ( $expiry ) {
				$coupon->set_date_expires( $expiry );
			}
			$coupon->save();
			$created[] = $code;
		}
	}
	echo '<div class="wrap"><h1>Μαζική δημιουργία κουπονιών</h1><form method="post">';
	wp_nonce_field( 'perfectpixel_bulk_coupons' );
	echo '<table class="form-table">';
	echo '<tr><th>Πλήθος (έως 500)</th><td><input type="number" name="count" value="10" min="1" max="500"></td></tr>';
	echo '<tr><th>Πρόθεμα κωδικού</th><td><input type="text" name="prefix" value="PROMO-"></td></tr>';
	echo '<tr><th>Τύπος έκπτωσης</th><td><select name="discount_type"><option value="percent">Ποσοστό %</option><option value="fixed_cart">Σταθερό ποσό καλαθιού</option><option value="fixed_product">Σταθερό ποσό προϊόντος</option></select></td></tr>';
	echo '<tr><th>Ποσό</th><td><input type="text" name="amount" value="10"></td></tr>';
	echo '<tr><th>Όριο χρήσης ανά κουπόνι</th><td><input type="number" name="usage_limit" value="1" min="0"> <span class="description">0 = απεριόριστο</span></td></tr>';
	echo '<tr><th>Λήξη</th><td><input type="date" name="expiry"></td></tr>';
	echo '</table>';
	submit_button( 'Δημιουργία κουπονιών', 'primary', 'perfectpixel_bulk_coupons' );
	echo '</form>';
	if ( $created ) {
		echo '<h2>' . count( $created ) . ' κουπόνια δημιουργήθηκαν</h2><textarea readonly rows="12" class="large-text code">' . esc_textarea( implode( "\n", $created ) ) . '</textarea>';
	}
	echo '</div>';
}
